KG42.register("rules-32df662f8468926f2e74ad19",{"id":"22-decentralized_flexibility_markets::v141-c-R007","paper":"22-decentralized_flexibility_markets","record":{"rule_id":"v141-c-R007","mechanism_id":"v141-a-M01","name":"Market payment","process_stage":"settlement","market_meaning":"The agreed local contract price specifies the amount the seller receives from the buyer for the contracted demand reduction. Scope: Bilateral flexibility contracts within the distribution-network market; prices are specific to individual contracts and metering intervals. Condition: For contracts agreed by their buyer and seller. Payments made by the DSO match the combined revenue accumulated by prosumers and aggregators in the reported outcomes. Scope: Reported simulation case-study outcomes in the flexibility market. Prosumers 46-55 receive no flexibility-market revenue because they do not participate. Scope: Agents labelled prosumers 46-55 in the reported simulation case studies. Condition: These agents do not participate in the flexibility market. Prosumers 1-30 must be compensated for their higher battery degradation costs and consequently receive significantly more revenue in Case Study B. Scope: Prosumers 1-30 in Case Study B. Condition: Their battery degradation costs are higher in Case Study B.","independence_rationale":"Relations governed by the approved function settlement.payment under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["pricing.local","settlement.payment"],"E":[{"edge_id":"v141-c-R007-E001","source":"pricing.local","target":"settlement.payment","type":"links","constraint_ids":["v141-c-R007-C001"],"evidence_ids":["v141-b-g01-E05","v141-b-g01-E08","v141-b-g01-E10"]}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Agents labelled prosumers 46-55 in the reported simulation case studies. | Bilateral flexibility contracts within the distribution-network market; prices are specific to individual contracts and metering intervals. | Prosumers 1-30 in Case Study B. | Reported simulation case-study outcomes in the flexibility market.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E05","v141-b-g01-E08","v141-b-g01-E10","v141-b-g03-E11"]},"x":[],"theta":[{"parameter_id":"param_contract_price","symbol":"p_\\omega","meaning":"Price specified by an agreed flexibility contract for trade ω; the amount the seller receives from the buyer for that contract.","value":{"kind":"symbolic","number_value":null,"text_value":"Contract-specific agreed price; no numeric value is specified for the general rule."},"unit":null,"indices":["ω"],"evidence_ids":["v141-b-g01-E08","v141-b-g01-E13","v141-b-g01-E22"]}],"phi":[{"constraint_id":"v141-c-R007-C001","kind":"mathematical","role":"core","statement":"The agreed local contract price specifies the amount the seller receives from the buyer for the contracted demand reduction. Scope: Bilateral flexibility contracts within the distribution-network market; prices are specific to individual contracts and metering intervals. Condition: For contracts agreed by their buyer and seller.","expression":"\\forall \\omega\\in\\Omega:\\ \\bigl[(\\omega,t_\\omega,p_\\omega)\\text{ is an agreed contract with buyer }b(\\omega)\\text{ and seller }s(\\omega)\\bigr]\\Rightarrow \\text{the seller }s(\\omega)\\text{ receives }p_\\omega\\text{ from the buyer }b(\\omega).","formalization_origin":"source","template_id":null,"members":["pricing.local","settlement.payment"],"variable_refs":[],"parameter_refs":["param_contract_price"],"evidence_ids":["v141-b-g01-E05","v141-b-g01-E08","v141-b-g01-E10","v141-b-g01-E13"]},{"constraint_id":"v141-c-R007-C002","kind":"procedural","role":"core","statement":"Payments made by the DSO match the combined revenue accumulated by prosumers and aggregators in the reported outcomes. Scope: Reported simulation case-study outcomes in the flexibility market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g03-E11"]},{"constraint_id":"v141-c-R007-C003","kind":"procedural","role":"core","statement":"Prosumers 46-55 receive no flexibility-market revenue because they do not participate. Scope: Agents labelled prosumers 46-55 in the reported simulation case studies. Condition: These agents do not participate in the flexibility market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g03-E11","v141-b-g02-e30"]},{"constraint_id":"v141-c-R007-C004","kind":"procedural","role":"core","statement":"Prosumers 1-30 must be compensated for their higher battery degradation costs and consequently receive significantly more revenue in Case Study B. Scope: Prosumers 1-30 in Case Study B. Condition: Their battery degradation costs are higher in Case Study B.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g03-E11","v141-b-g02-e29"]}],"pi":[{"evidence_id":"v141-b-g01-E05","location":{"location_id":"src-12c011a9b5-p03-c1r3__v141-a-M01-participation","page":3,"printed_page":null,"section":"II. Decentralized Flexibility Market Design","anchor_text":"[44]. Each prosumer has a retail supplier, which meters their th individual net energy use (e.g. dur","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"unknown"},"source_text":"The proposed flexibility market works alongside existing retail electricity market arrangements in a distribution network. It is assumed that the distribution network has a number of prosumers–consumers with flexible energy resources, and equipment for automated resource scheduling based on user settings, such as a building or home energy management system [44]. Each prosumer has a retail supplier, which meters their individual net energy use (e.g. during each 30 minute interval of the day). For each interval, each prosumer is charged for their net energy use, at prices which may be time-of-use dependent, and paid for their net exported energy [45]."},{"evidence_id":"v141-b-g01-E08","location":{"location_id":"src-12c011a9b5-p03-c2r2__v141-a-M01-participation","page":3,"printed_page":null,"section":"II. Decentralized Flexibility Market Design; Fig. 1","anchor_text":"mer xis- ce- ies ar- Fig. 1. A trading network for distribution system ﬂexibility between a DSO, , i","equation_id":null,"figure_id":"Fig. 1","table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"The flexibility market is made up of a network of potential flexibility contracts, with multiple contracts connecting each pair of agents that are able to trade with one another. Fig. 1 shows a high-level diagram of a trading network for distribution system flexibility. Each flexibility contract specifies a price the seller will receive from the buyer for reducing demand during a particular retail market metering interval."},{"evidence_id":"v141-b-g01-E10","location":{"location_id":"src-12c011a9b5-p03-c2r3__v141-a-M01-bidding","page":3,"printed_page":null,"section":"II. Decentralized Flexibility Market Design","anchor_text":"eir their willingness to accept a contract specifying a price for a unit of of demand reduction duri","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"unknown"},"source_text":"The agents reach mutual agreement on a set of agreed contracts and contract prices through an iterative price-negotiation mechanism. At each step of the market, agents select their favorite bundle of available upstream and downstream contracts, and over-demanded contracts have their prices increased. The process continues until no price changes occur during an iteration."},{"evidence_id":"v141-b-g03-E11","location":{"location_id":"src-12c011a9b5-p09-c1r4__v141-a-M01-validation","page":9,"printed_page":null,"section":"VI. Results; Fig. 13","anchor_text":"seﬂexibility market during case studies A and B. on Fig. 13 shows the total revenue accumulated by d","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-09.png","occurrence_role":"example"},"source_text":"Fig. 13 shows the total revenue accumulated by different groups of agents in the flexibility market. Most of the flexibility is provided by the prosumers with battery systems (prosumers 1-30), and thus they accumulate more revenue than the prosumers with electric vehicles (prosumers 31-45). Aggregator 1, which trades with prosumers 1-30, receives more revenue than aggregator 2, since it is responsible for coordinating more transactions. The revenue accumulated by the prosumers and aggregators is matched by the payments made by the DSO. Prosumers 46-55 receive no revenue since they do not participate in the flexibility market. Prosumers 1-30 recieve significantly more revenue during Case Study B since they must be compensated for their higher battery degradation costs."},{"evidence_id":"v141-b-g01-E13","location":{"location_id":"src-12c011a9b5-p04-c1r1__v141-a-M01-participation","page":4,"printed_page":null,"section":"III. Agent Preferences","anchor_text":"MORSTYN et al.: DESIGNING DECENTRALIZED MARKETS FOR DISTRIBUTION SYSTE large number of consumers and","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"unknown"},"source_text":"Let A be the set of agents in the trading network. In the flexibility market, the agents trade flexibility contracts for a set of time intervals \\(\\mathcal{T} = \\{1, \\ldots, T\\}\\). Each flexibility contract specifies a price for a flexibility trade, specifying an agreed reduction in demand during a particular time interval. Note that all trades specify the same energy quantity of demand reduction. Let \\(X\\) be the set of contracts between the agents. A contract \\(x \\in X\\) can be described by a tuple \\((\\omega, t_\\omega, p_\\omega)\\), where \\(\\omega \\in \\Omega\\) is a unique trade ID, \\(t_\\omega\\) is the time interval of the underlying trade and \\(p_\\omega\\) is the price specified by the contract for the trade. The trades underlying a set of contracts \\(X\\) are given by \\(\\tau(X) = \\{\\omega \\in \\Omega | (\\omega, t_\\omega, p_\\omega) \\in X\\}\\)."},{"evidence_id":"v141-b-g01-E22","location":{"location_id":"src-12c011a9b5-p04-c2r3__v141-a-M01-clearing","page":4,"printed_page":null,"section":"III.A Prosumer Preferences","anchor_text":"energy management system is a tool for local demand forecast- ing [49]. In the ﬂexibility market, fo","equation_id":"(4)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"In the flexibility market, for upstream contracts \\(Y_i\\) and downstream contracts \\(Z_i\\), prosumer \\(i\\)'s utility function is, \\(U_i(Y_i \\cup Z_i) = \\sum_{(\\omega,t_\\omega,p_\\omega)\\in Z_i}(p_\\omega+\\gamma_i t_\\omega) - \\sum_{(\\phi,t_\\phi,p_\\phi)\\in Y_i}(p_\\phi+\\gamma_i t_\\phi) + \\sum_{t\\in\\mathcal{T}} [ p^s_{it}[P^f_{it}-P^d_{it}-|Y_{it}|+|Z_{it}|]^+ - p^b_{it}[P^d_{it}-P^f_{it}+|Y_{it}|-|Z_{it}|]^+ - c_{2i}(P^f_{it}-|Y_{it}|+|Z_{it}|)^2 ],\\) if \\(\\underline{P}^f_{it} \\le P^f_{it}-|Y_{it}|+|Z_{it}| \\le \\bar{P}^f_{it}, \\forall t\\in\\mathcal{T},\\) \\(\\underline{E}_{i\\tau} \\le E_{i0}-\\sum_{t=1}^{\\tau}(P^f_{it}-|Y_{it}|+|Z_{it}|)\\le \\bar{E}_{i\\tau}, \\forall \\tau\\in\\mathcal{T},\\) \\(U_i(Y_i\\cup Z_i)=-\\infty, \\text{otherwise}. \\tag{4}\\)"},{"evidence_id":"v141-b-g02-e29","location":{"location_id":"src-12c011a9b5-p07-c2r4__v141-a-M01-participation","page":7,"printed_page":null,"section":"VI. Results","anchor_text":"p p y, one hour standard deviations. ity The prosumers face time-of-use dependent retail energy her ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"unknown"},"source_text":"The flexibility market occurs over a 24 hour period (from 8 am to 8 am), with contracts specifying an agreed decrease in load by 1 kW during a particular 30 minute interval. A market price increment of \\Delta p = £0.005/kWh is used. For prosumers 1–30, the increased battery degradation that occurs at higher output powers is modeled with a quadratic cost coefficient c_{2i}. For Case Study A, c_{2i} = £0.01/(kWh)^2, whereas in Case Study B the rate of degradation is higher, c_{2i} = £0.06/(kWh)^2. It is assumed the batteries start at their minimum energy level at 8 am and must be returned to this energy level by 8 am the next day. For prosumers 31–45, it is assumed they need to fully re-charge their electric vehicles between their arrival and departure times, and also have a preference for early charging, with \\gamma_i = £0.01/kWh/h. The aggregators incur a transaction cost of c_{1i} = £0.01 for each accepted upstream contract."},{"evidence_id":"v141-b-g02-e30","location":{"location_id":"src-12c011a9b5-p07-c2r3__v141-a-M01-participation","page":7,"printed_page":null,"section":"VI. Results","anchor_text":"istic veriﬁcation, the power ﬂows, losses and voltages resulting from the market outcome have been c","equation_id":null,"figure_id":"Fig. 4","table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"example"},"source_text":"The DSO organizes a flexibility market to limit the distribution network demand to 75 kW. There are two aggregators acting as intermediaries between the DSO and the prosumers. Aggregator 1 trades with prosumers 1–30 (the prosumers with home batteries) and aggregator 2 trades with prosumers 31–45 (the prosumers with electric vehicles). Note that prosumers 46–55 do not participate in the flexibility market since they do not have flexible energy resources."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":"No separate design or operational decision variable is introduced in this settlement rule: payment is a mapping from the agreed contract price p_ω to the seller's receipt. Contract selection belongs to clearing (R002) and price formation to pricing (R006).","empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-participation","v141-a-M01-pricing","v141-a-M01-validation"],"extras":{"decision_anchor":"settlement.payment","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E08","quote":"Each flexibility contract specifies a price the seller will receive from the buyer for reducing demand during a particular retail market metering interval."},{"evidence_id":"v141-b-g01-E10","quote":"The agents reach mutual agreement on a set of agreed contracts and contract prices through an iterative price-negotiation mechanism."},{"evidence_id":"v141-b-g01-E05","quote":"The proposed flexibility market works alongside existing retail electricity market arrangements in a distribution network."}],[{"evidence_id":"v141-b-g03-E11","quote":"The revenue accumulated by the prosumers and aggregators is matched by the payments made by the DSO."}],[{"evidence_id":"v141-b-g03-E11","quote":"Prosumers 46-55 receive no revenue since they do not participate in the flexibility market."}],[{"evidence_id":"v141-b-g03-E11","quote":"Prosumers 1-30 recieve significantly more revenue during Case Study B since they must be compensated for their higher battery degradation costs."}]],"C2_formalization":{"graph_sha256":"5c720849f40fae3a574c05953c8f51457802ecb5d6271d70a7ab0581a0733ab5","applicability":"formalized","reason":"R007 is formalized for C001, where the source states that an agreed flexibility contract (ω,t_ω,p_ω) specifies p_ω as the amount the seller receives from the buyer. C002-C004 remain not_formalized because the supplied source reports revenue accounting and case-study outcomes textually, without an explicit revenue-total or payment-balance equation or source-defined revenue variables. B evidence used here is unreviewed candidate support; no independent source verification is claimed.","bindings":[{"object_id":"param_contract_price","node_ids":["pricing.local","settlement.payment"],"edge_ids":["v141-c-R007-E001"],"rationale":"The agreed contract price is formed in pricing.local and passed along the frozen edge v141-c-R007-E001 into settlement.payment, where it is the seller's receipt for the agreed contract."},{"object_id":"v141-c-R007-C001","node_ids":["pricing.local","settlement.payment"],"edge_ids":["v141-c-R007-E001"],"rationale":"C001 formalizes the settlement mapping represented by the frozen edge: the price fixed for an agreed local flexibility contract is the amount paid by the buyer and received by the seller in settlement."}],"revision_requests":["No C.1 graph revision is requested for C001. For C002-C004, fuller formalization would require B evidence defining revenue totals or an explicit payment-balance equation; v141-b-g03-E11 alone states the accounting result descriptively."]}},"quarantined_references":[]}});
